  function normalizeLocale(raw){const v=String(raw||'').replace('_','-').toLowerCase();if(v.startsWith('ja'))return'ja';if(v.startsWith('zh'))return'zh-CN';if(v.startsWith('ko'))return'ko';if(v.startsWith('es'))return'es';if(v.startsWith('fr'))return'fr';if(v.startsWith('de'))return'de';if(v.startsWith('pt'))return'pt-BR';return'en';}
